    void age(){LinearLayout l=col();l.addView(header("Age Calculator"));EditText dob=e("Birth date yyyy-MM-dd");l.addView(dob);TextView o=t("Age",18,true);l.addView(o);l.addView(btn("Calculate",v->{try{Date d=new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(dob.getText().toString());Calendar a=Calendar.getInstance(),b=Calendar.getInstance();b.setTime(d);int y=a.get(1)-b.get(1),m=a.get(2)-b.get(2),day=a.get(5)-b.get(5);if(day<0){m--;day+=a.getActualMaximum(5);}if(m<0){y--;m+=12;}o.setText(y+" years, "+m+" months, "+day+" days");}catch(Exception z){o.setText("Use yyyy-MM-dd");}}));frame(l);}
