    void dateDiff(){LinearLayout l=col();l.addView(header("Date Difference"));EditText a=e("Start yyyy-MM-dd"),b=e("End yyyy-MM-dd");l.addView(a);l.addView(b);TextView o=t("Days",18,true);l.addView(o);l.addView(btn("Calculate",v->{try{o.setText(((parse(b.getText().toString()).getTime()-parse(a.getText().toString()).getTime())/86400000L)+" days");}catch(Exception z){o.setText("Invalid date");}}));frame(l);}
    void dateAdd(){LinearLayout l=col();l.addView(header("Add / Subtract Date"));EditText a=e("Date yyyy-MM-dd"),n=e("Days (+/-)");l.addView(a);l.addView(n);TextView o=t("Date",18,true);l.addView(o);l.addView(btn("Calculate",v->{try{Calendar c=Calendar.getInstance();c.setTime(parse(a.getText().toString()));c.add(5,(int)num(n));o.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime()));}catch(Exception z){o.setText("Invalid date");}}));frame(l);}
