    void conv(String title,String[] names,double[] factor){LinearLayout l=col();l.addView(header(title));EditText x=e("Value");Spinner a=new Spinner(this),b=new Spinner(this);a.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));b.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(x);l.addView(a);l.addView(b);TextView o=t("Result",18,true);l.addView(o);l.addView(btn("Convert",v->{double z=num(x)*factor[a.getSelectedItemPosition()]/factor[b.getSelectedItemPosition()];o.setText(fmt(z)+" "+names[b.getSelectedItemPosition()]);}));frame(l);}
    void temperature(){LinearLayout l=col();l.addView(header("Temperature Converter"));EditText x=e("Value");Spinner a=new Spinner(this),b=new Spinner(this);String[] n={"C","F","K"};a.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,n));b.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,n));l.addView(x);l.addView(a);l.addView(b);TextView o=t("Result",18,true);l.addView(o);l.addView(btn("Convert",v->{double z=num(x);int f=a.getSelectedItemPosition(),to=b.getSelectedItemPosition();double c=f==0?z:f==1?(z-32)*5/9:z-273.15;if(to==1)c=c*9/5+32;else if(to==2)c+=273.15;o.setText(fmt(c)+" "+n[to]);}));frame(l);}
    void currency(){LinearLayout l=col();l.addView(header("Currency Converter • Live + Offline"));EditText amt=e("Amount");Spinner from=new Spinner(this),to=new Spinner(this);String[] cur={"USD","EUR","GBP","INR","BDT","AED","SAR","JPY","CNY","CAD","AUD"};from.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cur));to.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cur));TextView status=t("Rate: not loaded",15,false),out=t("Result",20,true);l.addView(amt);l.addView(from);l.addView(to);l.addView(status);l.addView(out);l.addView(btn("Update Live Rates",v->loadRates(cur,status,out,amt,from,to)));l.addView(btn("Convert Using Cached/Live Rate",v->convertRate(cur,status,out,amt,from,to)));l.addView(t("Live source: open.er-api.com. Last successful rates are cached on the phone for offline use.",12,false));frame(l);loadRates(cur,status,out,amt,from,to);}
    void loadRates(String[] cur,TextView status,TextView out,EditText amt,Spinner from,Spinner to){status.setText("Updating live rates…");new Thread(()->{try{URL u=new URL("https://open.er-api.com/v6/latest/USD");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder s=new StringBuilder();String z;while((z=r.readLine())!=null)s.append(z);r.close();String json=s.toString();sp.edit().putString("rates",json).putLong("rates_time",System.currentTimeMillis()).apply();runOnUiThread(()->status.setText("Live rates updated: "+new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date()))); }catch(Exception ex){runOnUiThread(()->status.setText("Offline mode: using cached rates"));}}).start();}
    double rate(String json,String code){Matcher m=Pattern.compile("\\\""+Pattern.quote(code)+"\\\"\\s*:\\s*([0-9.Ee+-]+)").matcher(json);return m.find()?Double.parseDouble(m.group(1)):Double.NaN;}
    void convertRate(String[] cur,TextView status,TextView out,EditText amt,Spinner from,Spinner to){String j=sp.getString("rates","");double a=num(amt),rf=rate(j,cur[from.getSelectedItemPosition()]),rt=rate(j,cur[to.getSelectedItemPosition()]);if(Double.isNaN(rf)||Double.isNaN(rt)){status.setText("No cached rate. Connect once to update rates.");return;}out.setText(fmt(a*rt/rf)+" "+cur[to.getSelectedItemPosition()]);}
    @Override public void onBackPressed(){home();}
