class Expr {static double eval(String s){return new P(s).expr();}static class P{String s;int i;P(String s){this.s=s;}void sp(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}double expr(){double x=term();while(true){sp();if(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')){char c=s.charAt(i++);double y=term();x=c=='+'?x+y:x-y;}else return x;}}double term(){double x=factor();while(true){sp();if(i<s.length()&&(s.charAt(i)=='*'||s.charAt(i)=='/'||s.charAt(i)=='×'||s.charAt(i)=='÷')){char c=s.charAt(i++);double y=factor();x=(c=='/'||c=='÷')?x/y:x*y;}else return x;}}double factor(){sp();if(i<s.length()&&s.charAt(i)=='-'){i++;return-factor();}if(i<s.length()&&s.charAt(i)=='('){i++;double x=expr();sp();if(i>=s.length()||s.charAt(i++)!=')')throw new RuntimeException();return x;}int st=i;while(i<s.length()&&(Character.isDigit(s.charAt(i))||s.charAt(i)=='.'))i++;if(st==i)throw new RuntimeException();double v=Double.parseDouble(s.substring(st,i));sp();if(i<s.length()&&s.charAt(i)=='%'){i++;v/=100;}return v;}}}
